/* ===== Разбор данных: CSV, JSON, XML в таблицу {заголовки, строки}; числа и даты по-русски ===== */
const РАЗБОР = (() => {
  /* CSV: кавычки, переводы строк внутри кавычек, разделитель угадывается */
  function разделитель(текст){
    const строки = текст.split(/\r?\n/).filter(x => x.trim()).slice(0, 20);
    let лучш = ',', оценка = -1;
    for(const р of [';', ',', '\t', '|']){
      const n = строки.map(s => { let k = 0, в = false; for(const ch of s){ if(ch === '"') в = !в; else if(ch === р && !в) k++; } return k; });
      if(!n.length || !n[0]) continue;
      const одинаково = n.filter(x => x === n[0]).length / n.length;
      const о = одинаково * 100 + Math.min(n[0], 50);
      if(о > оценка){ оценка = о; лучш = р; }
