      if(т[lt + 1] === '?' || т[lt + 1] === '!'){ const e = т.indexOf('>', lt); i = e < 0 ? т.length : e + 1; continue; }
      let j = lt + 1, кав = null;
      while(j < т.length){ const ch = т[j]; if(кав){ if(ch === кав) кав = null; } else if(ch === '"' || ch === "'") кав = ch; else if(ch === '>') break; j++; }
      const тег = т.slice(lt + 1, j);
