}
/* ключевание счёта по БИК: три цифры от БИК + 20 цифр счёта, веса 7-1-3, сумма кратна 10 */
function счётВерен(счёт, бик){
  const с = String(счёт || '').replace(/\D/g, ''), б = String(бик || '').replace(/\D/g, '');
  if(с.length !== 20 || б.length !== 9) return false;
  const ркц = /^0[0-2]$/.test(б.slice(7)) && б.slice(6, 9) <= '002';
  const стр = (ркц ? '0' + б.slice(4, 6) : б.slice(6, 9)) + с;
  let s = 0; for(let i = 0; i < 23; i++) s += (+стр[i] * [7, 1, 3][i % 3]) % 10;
  return s % 10 === 0;
}
