/* старые выписки «Кодировка=DOS» — кодовая страница 866 */
function изDOS(б){ let s = ''; for(const b of б){ s += b < 0x80 ? String.fromCharCode(b) : b < 0xB0 ? String.fromCharCode(0x410 + b - 0x80) : b >= 0xE0 && b < 0xF0 ? String.fromCharCode(0x440 + b - 0xE0) : b === 0xF0 ? 'Ё' : b === 0xF1 ? 'ё' : ' '; } return s; }
/* ---------- разбор выписки ---------- */
function разобратьВыписку(текст){
  const строки = String(текст).replace(/^﻿/, '').split(/\r?\n/);
  if(!/^1CClientBankExchange/.test(строки[0] || '')) throw new Error('Это не файл обмена с 1С: первая строка должна быть «1CClientBankExchange»');
  const шапка = {}, счета = [], документы = [];
  let тек = null, где = 'шапка';
  for(const с of строки){
    const s = с.trim(); if(!s) continue;
    if(s === 'СекцияРасчСчет'){ тек = {}; где = 'счёт'; continue; }
    if(s === 'КонецРасчСчет'){ счета.push(тек); тек = null; где = 'шапка'; continue; }
    if(s.startsWith('СекцияДокумент')){ тек = {вид: s.split('=')[1] || 'Документ'}; где = 'док'; continue; }
    if(s === 'КонецДокумента'){ документы.push(тек); тек = null; где = 'шапка'; continue; }
    if(s === 'КонецФайла') break;
    const i = s.indexOf('='); if(i < 0) continue;
    const k = s.slice(0, i), v = s.slice(i + 1);
    if(где === 'шапка'){ if(k === 'РасчСчет'){ (шапка.РасчСчет = шапка.РасчСчет || []).push(v); } else шапка[k] = v; }
    else тек[k] = тек[k] ? тек[k] + ' ' + v : v;
  }
  return {шапка, счета, документы};
}
function нашиСчета(в){ return new Set([...(в.шапка.РасчСчет || []), ...в.счета.map(с => с.РасчСчет)].filter(Boolean)); }
/* документы → строки таблицы операций */
function операции(в){
  const наши = нашиСчета(в);
  const сч = (д, кто) => д[кто + 'РасчСчет'] || д[кто + 'Счет'];
  return в.документы.map(д => {
    const плСч = сч(д, 'Плательщик'), поСч = сч(д, 'Получатель');
    const приход = наши.has(поСч) && !наши.has(плСч) ? true : наши.has(плСч) && !наши.has(поСч) ? false : !!д.ДатаПоступило;
    const к = приход ? 'Плательщик' : 'Получатель';
    const имя = (д[к + '1'] || д[к] || '').replace(/^ИНН\s*\d+\s*/, '').trim();
    const наз = (д.НазначениеПлатежа || [1, 2, 3, 4, 5, 6].map(n => д['НазначениеПлатежа' + n] || '').join(' ')).trim();
    const ндс = /без\s+(налога\s*\(?)?НДС|НДС\s+не\s+облагается/i.test(наз) ? 'без НДС' : (() => { const m = наз.match(/НДС[^0-9%]{0,30}(\d{1,2}(?:[.,]\d+)?)\s*%[^0-9]{0,40}?(\d[\d\s]*[.,]\d{2})/i); return m ? деньги(m[2]) : null; })();
    const сумма = деньги(д.Сумма);
    return {дата: датаЧ(приход ? (д.ДатаПоступило || д.Дата) : (д.ДатаСписано || д.Дата)), номер: д.Номер || '', вид: д.вид, приход: приход ? сумма : null, расход: приход ? null : сумма,
      контрагент: имя, инн: д[к + 'ИНН'] || '', кпп: д[к + 'КПП'] || '', счёт: сч(д, к) || '', банк: (д[к + 'Банк1'] || '') + (д[к + 'Банк2'] ? ' ' + д[к + 'Банк2'] : ''), бик: д[к + 'БИК'] || '',
      назначение: наз, ндс, нашСчёт: приход ? поСч : плСч, датаДокумента: датаЧ(д.Дата)};
  });
}
/* сверка: начальный остаток + поступило − списано = конечный; суммы документов = итогам секции */
function сверка(в, оп){
  const out = [];
  for(const с of в.счета){
    const наш = оп.filter(о => о.нашСчёт === с.РасчСчет);
    const прих = наш.reduce((a, о) => a + (о.приход || 0), 0), расх = наш.reduce((a, о) => a + (о.расход || 0), 0);
    const н = деньги(с.НачальныйОстаток), к = деньги(с.КонечныйОстаток), вп = деньги(с.ВсегоПоступило), вс = деньги(с.ВсегоСписано);
    const беды = [];
    if(Math.abs(н + вп - вс - к) > 0.005) беды.push('остатки не сходятся: ' + руб(н) + ' + ' + руб(вп) + ' − ' + руб(вс) + ' ≠ ' + руб(к));
    if(с.ВсегоПоступило !== undefined && Math.abs(прих - вп) > 0.005) беды.push('поступления по документам ' + руб(прих) + ', в итогах выписки ' + руб(вп));
    if(с.ВсегоСписано !== undefined && Math.abs(расх - вс) > 0.005) беды.push('списания по документам ' + руб(расх) + ', в итогах выписки ' + руб(вс));
    out.push({счёт: с.РасчСчет, н, к, прих, расх, беды});
  }
  return out;
}

